import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/GET-DATA-_002fTYPE_003dPSQL.md","filePath":"manual-en/GET-DATA-_002fTYPE_003dPSQL.md","lastUpdated":1785684581000}'),r={name:"manual-en/GET-DATA-_002fTYPE_003dPSQL.md"};function n(i,e,d,c,l,m){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h4 id="_9-4-2-postgres-database-queries" tabindex="-1">9.4.2 Postgres Database Queries <a class="header-anchor" href="#_9-4-2-postgres-database-queries" aria-label="Permalink to &quot;9.4.2 Postgres Database Queries&quot;">​</a></h4><pre><code>GET DATA /TYPE=PSQL
         /CONNECT={connection info}
         /SQL={query}
         [/ASSUMEDSTRWIDTH=w]
         [/UNENCRYPTED]
         [/BSIZE=n].
</code></pre><p><code>GET DATA /TYPE=PSQL</code> imports data from a local or remote Postgres database server. It automatically creates variables based on the table column names or the names specified in the SQL query. PSPP cannot support the full precision of some Postgres data types, so data of those types will lose some precision when PSPP imports them. PSPP does not support all Postgres data types. If PSPP cannot support a datum, <code>GET DATA</code> issues a warning and substitutes the system-missing value.</p><p>The <code>CONNECT</code> subcommand is mandatory. It is a string specifying the parameters of the database server from which the data should be fetched. The format of the string is given in the postgres manual <a href="http://www.postgresql.org/docs/8.0/static/libpq.html#LIBPQ-CONNECT" target="_blank" rel="noreferrer">http://www.postgresql.org/docs/8.0/static/libpq.html#LIBPQ-CONNECT</a>.</p><p>The <code>SQL</code> subcommand is mandatory. It must be a valid SQL string to retrieve data from the database.</p><p>The <code>ASSUMEDSTRWIDTH</code> subcommand specifies the maximum width of string variables read from the database. If omitted, the default value is determined from the length of the string in the first value read for each variable.</p><p>The <code>UNENCRYPTED</code> subcommand allows data to be retrieved over an insecure connection. If the connection is not encrypted, and the <code>UNENCRYPTED</code> subcommand is not given, then an error occurs. Whether or not the connection is encrypted depends upon the underlying psql library and the capabilities of the database server.</p><p>The <code>BSIZE</code> subcommand serves only to optimise the speed of data transfer. It specifies an upper limit on number of cases to fetch from the database at once. The default value is 4096. If your SQL statement fetches a large number of cases but only a small number of variables, then the data transfer may be faster if you increase this value. Conversely, if the number of variables is large, or if the machine on which PSPP is running has only a small amount of memory, then a smaller value is probably better.</p><p>The following syntax is an example:</p><pre><code>GET DATA /TYPE=PSQL
     /CONNECT=&#39;host=example.com port=5432 dbname=product user=fred passwd=xxxx&#39;
     /SQL=&#39;select * from manufacturer&#39;.
</code></pre>`,10)])])}const f=a(r,[["render",n]]);export{h as __pageData,f as default};
